using System.Windows;using Crown___Sovereign.Services;namespace Crown___Sovereign.Views.Dialogs.Administracion;public partial class EmpleadoDialog:Window{public EmpleadoDialog(){InitializeComponent();RoleBox.ItemsSource=new[]{"Recepción","Limpieza","Mantenimiento","Servicios","Administración"};}private void Save_Click(object s,RoutedEventArgs e){try{new AdministracionService().CrearEmpleado(NameBox.Text,RoleBox.Text,EmailBox.Text,PhoneBox.Text);DialogResult=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,"No se pudo guardar",MessageBoxButton.OK,MessageBoxImage.Warning);}}private void Cancel_Click(object s,RoutedEventArgs e)=>Close();}
